  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fingerprints_employee_id_finger_unique` (`employee_id`,`finger`),
  KEY `fingerprints_device_id_template_hash_index` (`template_hash`),
